import { useState } from "react";

function App() {
  const [text, setText] = useState("");
  const [cvText, setCvText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    const res = await fetch("http://127.0.0.1:8000/extract", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ job_description: text, cv: cvText }),
    });

    const data = await res.json();
    setResult(data);
    setLoading(false);
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://127.0.0.1:8000/upload-cv", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();
    setCvText(data.text);
  };

  const score = result?.score || 0;

  return (
    <div className="p-6 text-white bg-slate-900 min-h-screen">
      <h1 className="text-2xl mb-4">AI Job Match Analyzer</h1>

      <textarea
        placeholder="Job description"
        value={text}
        onChange={(e) => setText(e.target.value)}
        className="w-full p-2 mb-2 bg-slate-800"
      />

      <textarea
        placeholder="Your CV"
        value={cvText}
        onChange={(e) => setCvText(e.target.value)}
        className="w-full p-2 mb-2 bg-slate-800"
      />

      <input type="file" onChange={handleFileUpload} />

      <button onClick={handleExtract} className="bg-blue-500 px-4 py-2 mt-2">
        {loading ? "Loading..." : "Analyze"}
      </button>

      {result && (
        <div className="mt-6">

          <h2>Score: {score}%</h2>
          <p>{result.explanation}</p>

          <h3>Core Skills</h3>
          <ul>
            {result.core_skills.map((s, i) => (
              <li key={i}>{s}</li>
            ))}
          </ul>

          <h3>All Skills</h3>
          <ul>
            {result.skills.map((s, i) => (
              <li key={i}>{s}</li>
            ))}
          </ul>

          {/* PAYWALL START */}

          <h3>🔒 Why You Get Rejected</h3>
          <p>Upgrade to see this</p>

          <h3>🔒 Priority Skills</h3>
          <p>Upgrade to see this</p>

          <h3>🔒 Missing Skills</h3>
          <p>Upgrade to see this</p>

        </div>
      )}
    </div>
  );
}

export default App;
